# Carefully limited starter records. Expand only with claim-level source verification.
ARTICLES = [
 {"id":"kerma","title":"Kerma civilization","period":"c. 2500–1500 BCE","region":"Present-day northern Sudan","category":"Civilizations","summary":"Kerma was a major early urban and political centre in the Middle Nile Valley. Archaeology documents monumental buildings, settlement remains, cemeteries and long-distance connections.","status":"Well supported","source_leads":[{"name":"UNESCO — Archaeological Sites of the Island of Meroe","url":"https://whc.unesco.org/en/list/1336/"},{"name":"University of Chicago — Institute for the Study of Ancient Cultures","url":"https://isac.uchicago.edu/"}],"note":"A concise orientation, not a complete article. Consult specialist publications on Kerma before adding detailed claims."},
 {"id":"kush","title":"Kingdom of Kush","period":"c. 2nd millennium BCE–4th century CE","region":"Nubia / Middle Nile Valley","category":"Civilizations","summary":"Kush was a powerful ancient state in Nubia. Its history includes the centres of Kerma, Napata and Meroë, and changing relationships with Egypt and other Nile Valley societies.","status":"Well supported","source_leads":[{"name":"UNESCO — Archaeological Sites of the Island of Meroe","url":"https://whc.unesco.org/en/list/1336/"},{"name":"British Museum collection","url":"https://www.britishmuseum.org/collection"}],"note":"Chronology and political phases require specialist sourcing; dates here are a broad orientation."},
 {"id":"meroe","title":"Meroë","period":"1st millennium BCE–4th century CE","region":"Present-day Sudan","category":"Places","summary":"Meroë was an important royal and urban centre of Kush. Its archaeological landscape includes royal cemeteries, temples and evidence of ironworking and settlement.","status":"Well supported","source_leads":[{"name":"UNESCO — Archaeological Sites of the Island of Meroe","url":"https://whc.unesco.org/en/list/1336/"}],"note":"Do not present contested interpretations of Meroitic language and society as settled facts."},
 {"id":"christian-nubia","title":"The Christian kingdoms of Nubia","period":"c. 5th–15th centuries CE","region":"Nubia, including parts of present-day Sudan","category":"Kingdoms & societies","summary":"Christian Nubia included the kingdoms commonly known as Nobadia, Makuria and Alwa. Their histories are reconstructed from written records, churches, inscriptions, manuscripts and archaeology; evidence is uneven across regions and periods.","status":"Scholarly overview","source_leads":[{"name":"Oxford Research Encyclopedia — Medieval/Christian Nubia","url":"https://academic.oup.com/edited-volume/61663/chapter-abstract/553492790"},{"name":"Cambridge University Press — Nubia, Darfur and Wadai","url":"https://www.cambridge.org/core/books/abs/medieval-africa-12501800/nubia-darfur-and-wadai/852AF7761863DDCCE98F9F0C1391ADFA"}],"note":"The three kingdoms did not have identical histories. Alwa is less well documented archaeologically and in surviving written sources."},
 {"id":"mahdist-state","title":"The Mahdist movement and state","period":"1881–1898","region":"Sudan","category":"Modern history","summary":"The Mahdist movement emerged under Muhammad Ahmad, who declared himself the Mahdi in 1881. It overthrew Turco-Egyptian rule in much of Sudan and established a state before its defeat by an Anglo-Egyptian force in 1898.","status":"Scholarly overview","source_leads":[{"name":"Oxford Research Encyclopedia — History of Sudanese Nationalism","url":"https://academic.oup.com/edited-volume/61663/chapter-abstract/553395408"},{"name":"Library of Congress — Anglo-Egyptian Sudan","url":"https://www.loc.gov/item/a22000955/"}],"note":"The movement's religious, social, regional and political dimensions should be explored through multiple Sudanese and scholarly perspectives."},
 {"id":"anglo-egyptian-rule","title":"Anglo-Egyptian rule","period":"1899–1955","region":"Sudan","category":"Modern history","summary":"The Anglo-Egyptian Condominium was the formal arrangement under which Britain and Egypt jointly administered Sudan. In practice, British officials exercised dominant authority. The period ended as Sudan moved to independence in 1956.","status":"Scholarly overview","source_leads":[{"name":"Oxford Academic — The Rule of the Anglo-Egyptian Condominium","url":"https://academic.oup.com/book/62898/chapter-abstract/563974660"},{"name":"Library of Congress — Anglo-Egyptian Sudan","url":"https://www.loc.gov/item/a22000955/"}],"note":"The formal joint arrangement and the unequal distribution of actual administrative power must both be explained."},
 {"id":"sudan-independence","title":"Sudan's independence","period":"1 January 1956","region":"Sudan","category":"Modern history","summary":"Sudan became independent on 1 January 1956 after the end of Anglo-Egyptian rule. Independence followed years of political organizing, constitutional negotiations and competing visions for the country's future.","status":"Verified event — expand sources","source_leads":[{"name":"Rift Valley Institute — The Sudan Handbook","url":"https://riftvalley.net/wp-content/uploads/2018/06/RVI-The-Sudan-Handbook.pdf"},{"name":"Encyclopaedia Britannica — Sudan","url":"https://www.britannica.com/place/Sudan"}],"note":"A full article should explain political negotiations, regional perspectives and the transition to independence."},
 {"id":"comprehensive-peace-agreement","title":"The Comprehensive Peace Agreement","period":"9 January 2005","region":"Sudan / Southern Sudan","category":"Modern history","summary":"The Government of Sudan and the Sudan People's Liberation Movement/Army signed the Comprehensive Peace Agreement in 2005. It ended the second north–south civil war and set out an interim period, power- and wealth-sharing arrangements, and a referendum on self-determination for the south.","status":"Primary document available","source_leads":[{"name":"United Nations Peacemaker — 2005 Sudanese Comprehensive Peace Agreement","url":"https://peacemaker.un.org/en/documents/2005-sudanese-comprehensive-peace-agreement"},{"name":"United Nations — UNMIS background","url":"https://peacekeeping.un.org/sites/default/files/past/unmis/background.shtml"}],"note":"Use the agreement itself for legal provisions; distinguish the text of the agreement from later implementation and political outcomes."},
 {"id":"south-sudan-independence","title":"Independence of South Sudan","period":"9 July 2011","region":"South Sudan","category":"Modern history","summary":"Following the 2005 peace agreement and a January 2011 referendum, South Sudan became an independent state on 9 July 2011. The referendum recorded an overwhelming vote for independence.","status":"Verified event — expand sources","source_leads":[{"name":"United Nations — Referendum in Southern Sudan","url":"https://peacekeeping.un.org/sites/default/files/past/unmis/referendum.shtml"},{"name":"United Nations — South Sudan member state","url":"https://www.un.org/en/about-us/member-states/south-sudan"}],"note":"A full article should include the referendum process, legal transition, citizenship questions and the experiences of communities on both sides of the new border."},
 {"id":"south-sudan-2013-conflict","title":"The South Sudan conflict beginning in 2013","period":"From December 2013","region":"South Sudan","category":"Modern history","summary":"Violence broke out in Juba on 15 December 2013 and spread to other parts of South Sudan, creating a major political, security and humanitarian crisis. The conflict had severe consequences for civilians and included ethnically targeted attacks documented by the United Nations.","status":"UN historical background","source_leads":[{"name":"United Nations Mission in South Sudan — Background","url":"https://unmiss.unmissions.org/en/unmiss-background"}],"note":"Avoid reducing the conflict to a simple ethnic explanation. Explain political, military, local and historical factors, and distinguish allegations from findings by investigative bodies."},
 {"id":"sudan-war-2023","title":"The war in Sudan","period":"From 15 April 2023","region":"Sudan","category":"Contemporary history","summary":"Fighting between the Sudanese Armed Forces and the Rapid Support Forces began on 15 April 2023. The war has caused widespread civilian harm, displacement and a severe humanitarian crisis. Its course and consequences continue to change.","status":"Ongoing — update with dated sources","source_leads":[{"name":"United Nations — Background on Sudan","url":"https://www.un.org/en/spotlight-on-sudan/background"},{"name":"UK House of Commons Library — The conflict in Sudan","url":"https://commonslibrary.parliament.uk/research-briefings/cbp-12177/"}],"note":"This is a living topic. Date every update, separate confirmed facts from claims by parties to the conflict, and prioritize current humanitarian and independent reporting."}
 ,
 {"id":"nubian-communities","title":"Nubian communities and languages","period":"Ancient to present","region":"Nile Valley in southern Egypt and northern Sudan","category":"Peoples & cultures","summary":"Nubian is an umbrella term used for communities with deep histories along the Middle Nile. Nubian languages include several varieties, and identities, dialects and cultural practices differ across communities and locations. Modern Nubian life has also been shaped by displacement associated with major dam projects and changing state borders.","status":"Research overview — expand with community voices","source_leads":[{"name":"UNESCO — Nubian monuments and the international campaign","url":"https://whc.unesco.org/en/activities/172/"},{"name":"Endangered Languages Project","url":"https://www.endangeredlanguages.com/"}],"note":"Do not treat Nubian identity or language as uniform. Add specific community names, self-identifications, oral histories and locally grounded scholarship."},
 {"id":"beja-communities","title":"Beja communities of the Red Sea region","period":"Ancient to present","region":"Eastern Sudan and neighbouring parts of the Red Sea region","category":"Peoples & cultures","summary":"Beja communities have long-standing histories in the Red Sea Hills and adjoining regions. Beja languages belong to the Cushitic branch of the Afroasiatic language family. Pastoralism, trade, mobility and changing political boundaries have all shaped regional histories, with varied experiences among Beja groups.","status":"Research overview — verify subgroup detail","source_leads":[{"name":"Encyclopaedia Britannica — Beja","url":"https://www.britannica.com/topic/Beja-people"},{"name":"Endangered Languages Project","url":"https://www.endangeredlanguages.com/"}],"note":"Avoid presenting all Beja communities as culturally or politically identical; verify subgroup names and preferred self-designations with specialist sources."},
 {"id":"fur-communities","title":"Fur communities and the history of Darfur","period":"Precolonial to present","region":"Darfur, western Sudan","category":"Peoples & cultures","summary":"The Fur are among the communities whose histories are central to Darfur. The historical Sultanate of Darfur was an important regional polity before its incorporation into the expanding Turco-Egyptian state in the nineteenth century. Fur experiences and identities are diverse and have been deeply affected by modern conflict and displacement.","status":"Research overview — source each historical period","source_leads":[{"name":"Encyclopaedia Britannica — Fur","url":"https://www.britannica.com/topic/Fur-people"},{"name":"UNESCO — Darfur and cultural heritage resources","url":"https://www.unesco.org/en"}],"note":"Darfur is home to many communities, not only the Fur. Do not conflate ethnic identity, political allegiance or the experiences of all residents."},
 {"id":"nuba-communities","title":"Nuba peoples of the Nuba Mountains","period":"Ancient to present","region":"Nuba Mountains, South Kordofan, Sudan","category":"Peoples & cultures","summary":"Nuba is a broad label for numerous communities in the Nuba Mountains, with substantial linguistic and cultural diversity. Communities have distinct histories, local identities and social traditions. The region's modern history includes conflict, displacement and political marginalisation.","status":"Research overview — diversity must remain visible","source_leads":[{"name":"Minority Rights Group — Sudan","url":"https://minorityrights.org/country/sudan/"},{"name":"Endangered Languages Project","url":"https://www.endangeredlanguages.com/"}],"note":"Never describe the Nuba as one single ethnic group or language. Build separate entries only where reliable, community-specific evidence is available."},
 {"id":"dinka-communities","title":"Dinka communities and histories","period":"Historical records to present","region":"Multiple regions of South Sudan, especially the Bahr el Ghazal and Upper Nile areas","category":"Peoples & cultures","summary":"Dinka (often self-referred to by the name Jieng in some contexts) encompasses multiple communities with distinct local histories and identities. Dinka languages belong to the Nilotic branch of the Eastern Sudanic language family. Cattle have important social, economic and cultural roles in many Dinka communities, though practices vary.","status":"Research overview — avoid generalisation","source_leads":[{"name":"Encyclopaedia Britannica — Dinka","url":"https://www.britannica.com/topic/Dinka"},{"name":"Minority Rights Group — South Sudan","url":"https://minorityrights.org/country/south-sudan/"}],"note":"Do not reduce Dinka society to cattle culture or imply all Dinka communities share one political position, dialect or custom."},
 {"id":"nuer-communities","title":"Nuer communities and histories","period":"Historical records to present","region":"South Sudan and adjacent areas of western Ethiopia","category":"Peoples & cultures","summary":"Nuer communities have histories across parts of what is now South Sudan and western Ethiopia. Nuer languages are Nilotic. Livelihoods have included pastoralism, cultivation, fishing and trade, shaped by seasonal environments and local histories. Political and social organisation varies across places and periods.","status":"Research overview — avoid generalisation","source_leads":[{"name":"Encyclopaedia Britannica — Nuer","url":"https://www.britannica.com/topic/Nuer"},{"name":"Minority Rights Group — South Sudan","url":"https://minorityrights.org/country/south-sudan/"}],"note":"Use ethnographic sources critically and historically; do not treat older colonial-era descriptions as timeless or definitive."},
 {"id":"shilluk-communities","title":"Shilluk (Chollo) communities and the kingdom of the Shilluk","period":"At least several centuries to present","region":"Western bank of the White Nile, especially around the Upper Nile region of South Sudan","category":"Peoples & cultures","summary":"The Shilluk, also known as Chollo, have a distinctive history associated with a kingdom along the White Nile. Their political institutions, oral traditions and relations with neighbouring communities have changed over time. Shilluk language belongs to the Nilotic language family.","status":"Research overview — oral and written sources needed","source_leads":[{"name":"Encyclopaedia Britannica — Shilluk","url":"https://www.britannica.com/topic/Shilluk"},{"name":"Minority Rights Group — South Sudan","url":"https://minorityrights.org/country/south-sudan/"}],"note":"Record Chollo/Shilluk naming carefully and include oral histories alongside documentary and academic sources, identifying the nature and date of each source."}

 ,
 {"id":"languages-of-sudan","title":"Languages of Sudan: a multilingual heritage","period":"Historical to present","region":"Sudan","category":"Culture & living heritage","summary":"Sudan is multilingual. Arabic is widely used, while many communities maintain other languages, including Nubian languages, Beja varieties, Fur, Masalit, Zaghawa and languages of the Nuba Mountains, among others. Language use and identity vary by region, generation and social context. Language policy has also been politically significant in modern Sudanese history.","status":"Research overview — community-level detail needed","source_leads":[{"name":"Oxford Academic — Arab Identity and Ideology in Sudan","url":"https://academic.oup.com/afraf/article/107/426/21/51550"},{"name":"British Council — Sudanese Intangible Cultural Heritage Archive","url":"https://cultural-protection-fund.britishcouncil.org/projects/iaas-archive-sudanese-intangible-heritage"}],"note":"This is not a complete language catalogue. Use linguist-authored sources for classifications and spellings, and community-preferred names for each language."},
 {"id":"oral-traditions-south-sudan","title":"Oral traditions and historical memory in South Sudan","period":"Across generations to present","region":"South Sudan","category":"Culture & living heritage","summary":"Oral traditions can preserve genealogies, accounts of migration, praise poetry, songs, proverbs, law and memories of political events. Their forms and meanings differ among communities. Oral accounts are historical sources that should be documented with the speaker, place, date, language and context, then compared carefully with other evidence rather than treated as interchangeable or automatically timeless.","status":"Research framework — document locally","source_leads":[{"name":"South Sudan Embassy — Cultural Practices in South Sudan","url":"https://southsudanembassy.be/en/products/south-sudan/culture/cultural-practices-in-south-sudan"},{"name":"Cambridge University Press — Bibliographical Note on the Ethnology of the Southern Sudan","url":"https://www.cambridge.org/core/journals/africa/article/abs/bibliographical-note-on-the-ethnology-of-the-southern-sudan/D156167D7AEBA18AABC4CD646F19A63B"}],"note":"Older ethnographic writing reflects its own era and assumptions. Prioritise contemporary scholarship and community-authorised oral history."},
 {"id":"sudan-living-heritage","title":"Living heritage in Sudan: rituals, crafts and social knowledge","period":"Living practices; selected UNESCO inscriptions 2021–2025","region":"Sudan","category":"Culture & living heritage","summary":"UNESCO's Sudan inventory includes Arabic calligraphy, date-palm knowledge and practices, metal engraving, celebrations of the Prophet Muhammad's birthday, henna practices and Al-Jertiq. These examples show how heritage can include skills, social knowledge, ritual, craft and intergenerational learning. They represent selected elements, not the full range of Sudanese cultural life.","status":"UNESCO-listed elements — see individual files","source_leads":[{"name":"UNESCO — Sudan intangible cultural heritage country page","url":"https://ich.unesco.org/en/state/sudan-SD"},{"name":"UNESCO — Al-Jertiq (inscribed 2025)","url":"https://ich.unesco.org/en/RL/al-jertiq-practices-rituals-and-expressions-for-preservation-protection-abundance-and-fertility-in-sudan-02275"}],"note":"Do not imply every Sudanese person practises these traditions. UNESCO inscriptions document particular practices and communities; they are not a complete national inventory."},
 {"id":"sudanese-music-archives","title":"Music, song and sound archives in Sudan","period":"Historical recordings to present","region":"Sudan","category":"Culture & living heritage","summary":"Music and song are part of social, ceremonial, religious and artistic life across Sudan's diverse communities. The University of Khartoum's Folklore and Traditional Music Archives have been the subject of a UNESCO-supported digital-preservation project, highlighting the importance of protecting recordings and their metadata. A responsible archive should identify performers, languages, communities, recording dates and permissions.","status":"Archival topic — recordings require rights and context","source_leads":[{"name":"UNESCO — Digital preservation of folklore and traditional music archives","url":"https://ich.unesco.org/en/assistances/digital-preservation-of-folklore-and-traditional-music-archives-phase-i-00488"},{"name":"British Council — Sudanese Intangible Cultural Heritage Archive","url":"https://cultural-protection-fund.britishcouncil.org/projects/iaas-archive-sudanese-intangible-heritage"}],"note":"Do not upload audio without checking copyright, performer consent, cultural restrictions and the archive's access conditions."},
 {"id":"food-and-dress-south-sudan","title":"Foodways and clothing across South Sudan","period":"Historical to present","region":"South Sudan","category":"Culture & living heritage","summary":"Food and clothing practices vary widely across South Sudan's communities and environments. Riverine fishing, livestock keeping, cultivation, markets and trade all shape local diets in different ways. Clothing ranges from contemporary urban styles to locally specific ceremonial and everyday dress. No single dish or outfit represents the whole country.","status":"Introductory overview — needs local documentation","source_leads":[{"name":"South Sudan Embassy — Cultural Practices in South Sudan","url":"https://southsudanembassy.be/en/products/south-sudan/culture/cultural-practices-in-south-sudan"},{"name":"ICCROM — Western Sudan Community Museums Project","url":"https://www.iccrom.org/sites/default/files/publications/2023-10/western_sudan_community_museums_iccrom_updated_oct2023_compressed.pdf"}],"note":"Build regional and community-specific entries using interviews, recipes, photographs and museum collections with consent and clear dates."}

]
